import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent } from '@domg-wc/components/atom';
import { VlProzaMessage } from '@domg-wc/components/block';

registerWebComponents([VlProzaMessage, VlButtonComponent, VlLinkComponent]);

// vl-proza-message haalt elk bericht op met GET proza/domein/{domain}/{code}, relatief tegenover de huidige url (of
// vanaf base-url), en toont het veld tekst van het antwoord, bv. { "code": "inline", "tekst": "Inline" }. De tekst
// mag html zijn; staat er een block-element in, dan zet de component zelf het attribuut block.
// Daarnaast vraagt hij per domein GET proza/domein/{domain}/toegelatenoperaties. In deze story antwoordt de server
// { "create": false, "read": true, "update": false, "delete": false }: zonder update geen edit- en refresh-knop.

import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent } from '@domg-wc/components/atom';
import { VlProzaMessage } from '@domg-wc/components/block';

registerWebComponents([VlProzaMessage, VlButtonComponent, VlLinkComponent]);

// Editeerbaar wordt een bericht als GET proza/domein/{domain}/toegelatenoperaties update: true geeft, in deze story
// { "create": true, "read": true, "update": true, "delete": true }. Dan toont vl-proza-message naast de tekst een
// edit-knop, die /proza/domeinen/{domain}/codes/{code} in een nieuw venster opent, en een refresh-knop, die het
// bericht opnieuw ophaalt zonder de cache van de browser.
